// Workflow 01 · Stage A - authenticate the caller before anything else runs.
// Until 2026-11-25 (security audit F1) this graph had NO inbound check: it went
// straight from the webhook to Django's public booking endpoint, and the only
// shield was a 5-per-10-minutes cache counter keyed on a header the caller
// controls. Workflows 04/05/07/08 already verify first; 01 now copies them.
//
// Fail closed: an unset DJANGO_WEBHOOK_SECRET rejects EVERY request, because an
// unconfigured receiver must never accept traffic. No fallback value is allowed
// here - the old dev literal is published in this repository and is retired.
const src = $input.first().json || {};
const headers = src.headers || {};

const env = (name) => { try { const v = $env[name]; return v == null ? '' : String(v); } catch (e) { return ''; } };

const expected = env('DJANGO_WEBHOOK_SECRET');
const provided = String(headers['x-webhook-secret'] || '').trim();
const authorized = Boolean(expected) && provided === expected;

return [{ json: {
  ...src,
  intake_auth: {
    authorized: authorized,
    reason: authorized ? null : (expected ? 'bad_secret' : 'secret_not_configured'),
  },
} }];

// Workflow 01 · Stage B — normalize an intake from the Web Form, WhatsApp Flow
// or Telegram bot into EXACTLY the body Django's BookingRequestCreateSerializer
// reads, and compose the outbound request in code so the HTTP node never
// re-templates patient input (a quote in a name used to break the JSON) and
// never appends /api/v1 to a base that already includes it.
const item = $input.item.json;
const body = item.body || item;

// 1. Normalize Phone to E.164 (+234 standard for Nigeria / international fallback)
let phone = String(body.phone || body.patient_phone || '').trim().replace(/[^0-9+]/g, '');
if (phone.startsWith('0') && phone.length === 11) {
  phone = '+234' + phone.substring(1);
} else if (!phone.startsWith('+') && phone.length >= 10) {
  phone = '+' + phone;
}

// 2. Validate Service and Patient Name
const patientName = String(body.patient_name || body.name || 'Valued Patient').trim();
const serviceId = body.service_id || body.service || null;
const doctorId = body.doctor_id || body.preferred_doctor_id || null;
const channel = (body.channel || 'web').toLowerCase();
const telegramChatId = body.telegram_chat_id || body.chat_id || null;
const preferredWindow = body.preferred_time_window || 'morning';
const notes = body.notes || body.patient_notes || '';

// 3. Preferred dates formatting (default to next 14 days if not provided)
let preferredDates = body.preferred_dates;
if (!preferredDates || !Array.isArray(preferredDates) || preferredDates.length === 0) {
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const inTwoWeeks = new Date(today);
  inTwoWeeks.setDate(inTwoWeeks.getDate() + 14);
  preferredDates = [tomorrow.toISOString().split('T')[0], inTwoWeeks.toISOString().split('T')[0]];
}

// 4. The outbound contract, built in code.
//    Django reads `patient_name` / `patient_phone` (serializers_booking.py);
//    `service_id` is a CharField WITHOUT allow_null, so the key is omitted
//    when the intake did not name a service - never sent as null.
const django_body = {
  patient_name: patientName,
  patient_phone: phone,
  preferred_dates: preferredDates,
  preferred_time_window: preferredWindow,
  channel: channel,
  patient_notes: notes,
};
if (serviceId) django_body.service_id = String(serviceId);
if (doctorId) django_body.preferred_doctor_id = String(doctorId);

// Fail-closed transport: the env base already includes /api/v1 (see the build
// sheet's URL contract), and NO fallback host or secret exists. An unset env
// var must fail loudly in this workflow, not post to a guessed server.
const apiBase = String($env.DJANGO_API_BASE_URL || '').replace(/\/+$/, '');
const djangoUrl = apiBase ? apiBase + '/booking-requests/' : '';
const webhookSecret = String($env.DJANGO_WEBHOOK_SECRET || '');

return {
  json: {
    patient_name: patientName,
    phone: phone,
    service_id: serviceId,
    preferred_doctor_id: doctorId,
    preferred_dates: preferredDates,
    preferred_time_window: preferredWindow,
    channel: channel,
    telegram_chat_id: telegramChatId,
    patient_notes: notes,
    raw_received_at: new Date().toISOString(),
    django_url: djangoUrl,
    secret: webhookSecret,
    django_body: django_body,
  }
};

